const str = { type: 'string', minLength: 1 };
const text = { type: 'string' };
const bool = { type: 'boolean' };
const num = { type: 'number' };
const index = { type: 'integer', minimum: 0 };
const obj = (properties: Record<string, AnySchema>, required = Object.keys(properties)): AnySchema => ({ type: 'object', properties, required });
const arr = (items: AnySchema): AnySchema => ({ type: 'array', items });
const choice = (...schemas: AnySchema[]): AnySchema => ({ anyOf: schemas });
const literal = (value: string): AnySchema => ({ const: value });
const strings = arr(text);
const rpcId = choice(str, { type: 'integer' });
