const claudeRequest = choice(claudeInput, claudePermission, claudeQuery, obj({ method: literal('Query.interrupt'), queryHandle: str }));
const claudeResult = obj({ type: literal('result'), subtype: { enum: ['success', 'error_during_execution', 'error_max_turns', 'error_max_budget_usd', 'error_max_structured_output_retries'] }, is_error: bool, stop_reason: nullable(text), terminal_reason: text, session_id: str, uuid: str, result: text, errors: strings }, ['type', 'subtype', 'is_error', 'stop_reason', 'session_id', 'uuid']);
